import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 4

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Identify strong univariate associations
    strong_features = []
    for i, fid in enumerate(feats.ids):
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if p_val < 0.05:
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            strong_features.append((fid, mean_diff, abs(t_stat), p_val))

    # Sort by statistical significance
    strong_features.sort(key=lambda x: x[2], reverse=True)

    # Remove near-duplicates
    unique_features = set()
    for fid, _, _, _ in strong_features:
        keep = True
        for dup_pair in correlated_pairs:
            if fid in dup_pair:
                # Keep only one from each pair
                if any(f in unique_features for f in dup_pair):
                    keep = False
                    break
                else:
                    unique_features.add(fid)
                    break
        if keep:
            unique_features.add(fid)

    # Try to find a mechanism using cross-validation within strata
    drivers = []
    columns = []
    products = []
    loadings = {}

    # If no strong features, return empty design
    if not strong_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use top features as candidates
    candidate_features = [f[0] for f in strong_features[:10]]

    # Test for interaction effects among top features
    if len(candidate_features) > 1:
        # Look for interactions between top features
        for fid1 in candidate_features[:5]:
            for fid2 in candidate_features[:5]:
                if fid1 != fid2:
                    col1 = feats.column(fid1)
                    col2 = feats.column(fid2)
                    prod = feats.x[:, col1] * feats.x[:, col2]

                    # Test if product improves model
                    X = np.column_stack([feats.x[:, feats.column(fid)] for fid in candidate_features[:5]])
                    y = feats.y

                    # Simple logistic regression test
                    try:
                        lr = LogisticRegression(fit_intercept=False, max_iter=1000)
                        lr.fit(X, y)
                        base_score = lr.score(X, y)

                        X_with_prod = np.column_stack([X, prod])
                        lr2 = LogisticRegression(fit_intercept=False, max_iter=1000)
                        lr2.fit(X_with_prod, y)
                        prod_score = lr2.score(X_with_prod, y)

                        if prod_score > base_score + 0.01:  # Significant improvement
                            products.append((fid1, fid2))
                    except:
                        pass

    # For simplicity, just use top few features
    selected_features = candidate_features[:MAX_DRIVERS]

    # Check if we can build a reasonable model
    if len(selected_features) > 0:
        # Weighted score approach
        for fid in selected_features:
            col_idx = feats.column(fid)
            # Simple correlation-based weighting
            corr = np.corrcoef(feats.x[:, col_idx], feats.y)[0, 1]
            loadings[fid] = corr

        # Use all selected features as columns
        columns = selected_features

        # Select top features as potential drivers
        drivers = [fid for fid, _, _, _ in strong_features if fid in selected_features][:MAX_DRIVERS]

    # Final check: ensure no spurious correlations
    if len(drivers) == 0 and len(columns) == 0:
        # No evidence of mechanism
        return Design(drivers=(), columns=(), products=(), loadings={})

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
